-- 푸시 알림 발송에 쓰는 기기 토큰(notification/domain/DeviceToken)과 시간대별 수신 설정(notification/domain/NotificationPreference).
-- FCM 호출과 발송 시각 판단은 별도 발송기가 맡고, 이 저장소는 토큰과 설정만 보관한다.

-- FCM 등록 토큰은 기기마다 하나라 token이 유니크다. 같은 기기에서 다른 계정으로 로그인하면 행을 새로 만들지 않고 user_id를 바꾼다.
-- last_seen_at은 앱이 토큰을 마지막으로 보고한 시각이며 Instant라 TIMESTAMPTZ로 둔다.
CREATE TABLE "device_tokens" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" BIGINT NOT NULL REFERENCES "users" ("id"),
    "token" VARCHAR(512) NOT NULL,
    "platform" VARCHAR(10) NOT NULL,
    "last_seen_at" TIMESTAMPTZ NOT NULL,
    "created_at" TIMESTAMP NOT NULL,
    CONSTRAINT "uk_device_tokens_token" UNIQUE ("token")
);

-- 발송 대상 회원의 토큰을 모으고 탈퇴 시 회원의 토큰을 지운다. 엔티티 @Index와 이름·컬럼을 맞춘다.
CREATE INDEX "idx_device_tokens_user_id" ON "device_tokens" ("user_id");

-- 회원·시간대(MORNING·NOON·EVENING)당 한 행이라 (user_id, slot)이 유니크다. 발송 시각은 발송기의 코드 상수라 DB에 두지 않는다.
CREATE TABLE "notification_preferences" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" BIGINT NOT NULL REFERENCES "users" ("id"),
    "slot" VARCHAR(10) NOT NULL,
    "enabled" BOOLEAN NOT NULL,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP NOT NULL,
    CONSTRAINT "uk_notification_preferences_user_id_slot" UNIQUE ("user_id", "slot")
);

-- 발송기가 시간대마다 수신을 켠 회원을 찾는다. 엔티티 @Index와 이름·컬럼을 맞춘다.
CREATE INDEX "idx_notification_preferences_slot_enabled" ON "notification_preferences" ("slot", "enabled");
